def solve(clue):
    w = clue.index('\n') + 1
    n = len(clue)
    s = clue.index('S'); e = clue.index('E')
    prev = {s: None}
    q = collections.deque([s])
    while q:
        i = q.popleft()
        if i == e:
            break
        for m, d in (('U', -w), ('D', w), ('L', -1), ('R', 1)):
            j = i + d
            if 0 <= j < n and clue[j] in '.E' and j not in prev:
                prev[j] = (i, m); q.append(j)
    out = []; i = e
    while prev[i]:
        i, m = prev[i]; out.append(m)
    return ''.join(out[::-1])

